import os
from dataclasses import dataclass, field

import tkinter as tk
import tkinter.ttk as ttk
from tkinter import messagebox, filedialog

import pyvisa

import Rigol_Controller
import gui_utils
import config_store
from rigol_psu import RigolPSU
import psu_discovery
from mock_psu import MockRigolPSU, find_mock_supplies
from tooltip import Tooltip

PANEL_GUTTER = 10
STATUS_POLL_MS = 2000

# Set RIGOL_MOCK=1 to drive the whole app (including the 2nd-panel
# duplication) with two simulated supplies, no hardware or VISA backend
# required. See test_gui_mock.bat.
MOCK_MODE = os.environ.get('RIGOL_MOCK') == '1'

root = None
rm = None
panels = []


@dataclass
class ChannelWidgets:
    channel_number: int
    voltage_entry: tk.Entry
    current_entry: tk.Entry
    toggle_button: tk.Button


@dataclass
class PSUPanel:
    frame: tk.Frame
    combobox: ttk.Combobox
    combobox_var: tk.StringVar
    channels: list
    psu: RigolPSU = None
    resources: list = field(default_factory=list)


def main(*args):
    '''Main entry point for the application.'''
    global root, rm, panels
    root = tk.Tk()
    rm = None
    panels = []
    root.protocol('WM_DELETE_WINDOW', _on_close)

    global _top1, _w1
    _top1 = root
    _w1 = Rigol_Controller.Rigol_GUI(_top1)

    if MOCK_MODE:
        root.title(root.title() + ' — MOCK MODE (no hardware)')

    _w1.menubar.add_command(label='Save Settings', compound='left', command=SaveSettings)
    _w1.menubar.add_command(label='Load Settings', compound='left', command=LoadSettings)

    panel1 = _build_panel1(_w1)
    _bind_panel(panel1)
    panels.append(panel1)

    root.after(STATUS_POLL_MS, _refresh_all_statuses)
    root.mainloop()


def FindPS(*args):
    gui = _w1
    try:
        if MOCK_MODE:
            found = find_mock_supplies()
        else:
            resource_manager = _get_resource_manager()
            found = psu_discovery.find_rigol_supplies(resource_manager)
    except Exception as e:
        messagebox.showerror('VISA Error', f'Error while searching for power supplies: {e}')
        return

    if not found:
        messagebox.showinfo('Find Power Supplies', 'No Rigol power supplies were found.')
        return

    if len(found) >= 2 and len(panels) < 2:
        panel2 = _build_panel2(gui, panels[0])
        _bind_panel(panel2)
        panels.append(panel2)

    labels = [_resource_label(res, idn) for res, idn in found]
    for panel in panels:
        panel.resources = found
        panel.combobox.configure(values=labels)


def SaveSettings(*args):
    '''Save every connected panel's current Voltage/Current entry values,
    keyed by instrument IDN so they still apply after reconnecting to a
    different USB port.'''
    data = {}
    saved_channels = 0
    for panel in panels:
        if panel.psu is None:
            continue
        for ch in panel.channels:
            try:
                voltage = float(ch.voltage_entry.get())
                current = float(ch.current_entry.get())
            except ValueError:
                continue
            config_store.set_channel_settings(data, panel.psu.idn, ch.channel_number, voltage, current)
            saved_channels += 1

    if saved_channels == 0:
        messagebox.showinfo('Save Settings',
                             'No connected power supply with valid Voltage/Current values to save.')
        return

    path = filedialog.asksaveasfilename(
        title='Save Power Supply Settings',
        defaultextension='.json',
        initialfile='psu_settings.json',
        filetypes=[('JSON files', '*.json'), ('All files', '*.*')],
    )
    if not path:
        return

    try:
        config_store.save(path, data)
    except Exception as e:
        messagebox.showerror('Save Settings', f'Could not save settings: {e}')
        return

    messagebox.showinfo('Save Settings', f'Saved {saved_channels} channel setting(s) to:\n{path}')


def LoadSettings(*args):
    '''Load Voltage/Current values into the entry boxes of any panel whose
    connected supply's IDN matches an entry in the file. Does not write
    anything to the instrument - click a channel's button to apply and
    turn it on, same as always.'''
    path = filedialog.askopenfilename(
        title='Load Power Supply Settings',
        filetypes=[('JSON files', '*.json'), ('All files', '*.*')],
    )
    if not path:
        return

    try:
        data = config_store.load(path)
    except Exception as e:
        messagebox.showerror('Load Settings', f'Could not load settings: {e}')
        return

    loaded_channels = 0
    for panel in panels:
        if panel.psu is None:
            continue
        for ch in panel.channels:
            settings = config_store.get_channel_settings(data, panel.psu.idn, ch.channel_number)
            if settings is None:
                continue
            ch.voltage_entry.delete(0, tk.END)
            ch.voltage_entry.insert(0, str(settings['voltage']))
            ch.current_entry.delete(0, tk.END)
            ch.current_entry.insert(0, str(settings['current']))
            loaded_channels += 1

    if loaded_channels == 0:
        messagebox.showinfo('Load Settings',
                             'No saved settings matched a currently connected supply.\n'
                             'Select a supply in each panel first, then load again.')
    else:
        messagebox.showinfo('Load Settings',
                             f'Loaded {loaded_channels} channel setting(s) into the entry boxes.\n'
                             'Click each channel\'s button to apply and turn it on.')


def _resource_label(resource_name, idn):
    return f'{idn} ({resource_name})'


def _get_resource_manager():
    global rm
    if rm is None:
        rm = pyvisa.ResourceManager()
    return rm


def _widen_combobox(gui, fraction=0.9):
    '''The PAGE-designed combobox is too narrow to read a full IDN string -
    widen it to `fraction` of Frame1's width, centered. Runs before
    _build_panel2 ever clones Frame1, so panel 2's combobox inherits the
    same width automatically.'''
    frame_width = int(gui.Frame1.place_info()['width'])
    combo_width = round(frame_width * fraction)
    margin = (frame_width - combo_width) // 2
    gui.TC1_PSChoice.place(x=margin, width=combo_width)


def _build_panel1(gui):
    '''Populate the two empty channel frames from the fully-designed
    FrChan1, then wrap panel 1's widgets in a PSUPanel.'''
    _widen_combobox(gui)

    map_ch2 = gui_utils.clone_widget_tree(gui.FrChan1, gui.FrChan2)
    map_ch3 = gui_utils.clone_widget_tree(gui.FrChan1, gui.FrChan3)

    # Label3 is the "Output Settings" title already sitting in each channel
    # frame - retext it per channel instead of adding a new widget. Panel 2
    # inherits this correctly too: _build_panel2 clones these frames as-is,
    # carrying the already-set "Channel N" text along with them.
    gui.Label3.configure(text='Channel 1')
    map_ch2[gui.Label3].configure(text='Channel 2')
    map_ch3[gui.Label3].configure(text='Channel 3')

    channels = [
        ChannelWidgets(1, gui.Entry1, gui.Entry2, gui.Button1),
        ChannelWidgets(2, map_ch2[gui.Entry1], map_ch2[gui.Entry2], map_ch2[gui.Button1]),
        ChannelWidgets(3, map_ch3[gui.Entry1], map_ch3[gui.Entry2], map_ch3[gui.Button1]),
    ]

    return PSUPanel(
        frame=gui.Frame1,
        combobox=gui.TC1_PSChoice,
        combobox_var=gui.combobox,
        channels=channels,
    )


def _build_panel2(gui, panel1):
    '''Clone the whole of panel 1's frame (now fully populated) to the
    right, and widen the window to fit it.'''
    top = gui.top
    frame1 = panel1.frame
    info = frame1.place_info()
    frame1_x, frame1_y = int(info['x']), int(info['y'])
    frame1_w, frame1_h = int(info['width']), int(info['height'])

    frame2_x = frame1_x + frame1_w + PANEL_GUTTER
    frame2 = tk.Frame(top)
    gui_utils.apply_options(frame2, frame1)
    frame2.place(x=frame2_x, y=frame1_y, width=frame1_w, height=frame1_h)

    clone_map = gui_utils.clone_widget_tree(frame1, frame2)

    combobox2 = clone_map[panel1.combobox]
    combobox2_var = tk.StringVar()
    combobox2.configure(textvariable=combobox2_var)

    channels = [
        ChannelWidgets(
            ch.channel_number,
            clone_map[ch.voltage_entry],
            clone_map[ch.current_entry],
            clone_map[ch.toggle_button],
        )
        for ch in panel1.channels
    ]

    root.update_idletasks()
    new_width = frame2_x + frame1_w + frame1_x
    top.geometry(f'{new_width}x{top.winfo_height()}')

    return PSUPanel(
        frame=frame2,
        combobox=combobox2,
        combobox_var=combobox2_var,
        channels=channels,
    )


def _bind_panel(panel):
    panel.combobox.bind('<<ComboboxSelected>>', lambda event, p=panel: _on_resource_selected(p))
    Tooltip(panel.combobox, panel.combobox_var.get)
    for ch in panel.channels:
        ch.toggle_button.configure(command=lambda p=panel, c=ch: _toggle_channel(p, c))


def _on_resource_selected(panel):
    label = panel.combobox_var.get()
    match = next((res for res, idn in panel.resources if _resource_label(res, idn) == label), None)
    if match is None:
        return

    if panel.psu is not None:
        panel.psu.close()
        panel.psu = None

    psu_cls = MockRigolPSU if MOCK_MODE else RigolPSU
    psu = psu_cls(rm, match)
    try:
        psu.connect()
    except Exception as e:
        messagebox.showerror('Connection Error', f'Could not connect to {match}: {e}')
        return

    panel.psu = psu
    _refresh_panel_status(panel)


def _toggle_channel(panel, ch):
    if panel.psu is None:
        messagebox.showwarning('No Power Supply', 'Select a power supply first.')
        return

    try:
        voltage = float(ch.voltage_entry.get())
        current = float(ch.current_entry.get())
    except ValueError:
        messagebox.showerror('Invalid Value', 'Voltage and current must be numbers.')
        return

    try:
        currently_on = panel.psu.is_output_on(ch.channel_number)
        panel.psu.set_voltage(ch.channel_number, voltage)
        panel.psu.set_current(ch.channel_number, current)
        panel.psu.set_output(ch.channel_number, not currently_on)
    except Exception as e:
        messagebox.showerror('VISA Error', f'Channel {ch.channel_number}: {e}')
        return

    _refresh_channel_status(panel, ch)


def _refresh_channel_status(panel, ch):
    try:
        on = panel.psu.is_output_on(ch.channel_number)
    except Exception:
        return
    ch.toggle_button.configure(text='Turn Channel Off' if on else 'Turn Channel On')


def _refresh_panel_status(panel):
    if panel.psu is None:
        return
    for ch in panel.channels:
        _refresh_channel_status(panel, ch)


def _refresh_all_statuses():
    for panel in panels:
        _refresh_panel_status(panel)
    if root is not None:
        root.after(STATUS_POLL_MS, _refresh_all_statuses)


def _on_close():
    for panel in panels:
        if panel.psu is not None:
            panel.psu.close()
    if rm is not None:
        rm.close()
    root.destroy()


if __name__ == '__main__':
    Rigol_Controller.start_up()
